-- Reviewed senior batch 007; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":3144,"word":"ballot","meaning":"選票","example":"Each student placed a ballot in the box to choose the club president.","example_zh":"每位學生把選票投入票箱，選出社長。","original_meaning":"選票","original_example":"Citizens cast their votes using a ballot.","original_example_zh":"公民透過選票行使投票權。"},{"source_id":3145,"word":"bandwidth","meaning":"頻寬","example":"The school's limited bandwidth made the video lesson load slowly.","example_zh":"學校頻寬有限，讓影片課程載入緩慢。","original_meaning":"頻寬","original_example":"The network provides high-speed bandwidth.","original_example_zh":"該網路提供高速頻寬。"},{"source_id":3146,"word":"bane","meaning":"禍根","example":"The persistent weeds were the bane of our school garden.","example_zh":"頑強的雜草是我們校園菜園的一大禍根。","original_meaning":"禍根","original_example":"Pollution is a bane to the environment.","original_example_zh":"污染是環境的禍害。"},{"source_id":3147,"word":"barricade","meaning":"路障","example":"The workers placed a barricade across the damaged path.","example_zh":"工人在受損步道前設置路障。","original_meaning":"路障","original_example":"Protesters built a barricade on the street.","original_example_zh":"抗議者在街上築起路障。"},{"source_id":3148,"word":"battalion","meaning":"營","example":"The museum model showed a battalion marching across an old bridge.","example_zh":"博物館模型呈現一個營的士兵走過老橋。","original_meaning":"營","original_example":"The soldiers advanced as a battalion.","original_example_zh":"士兵們以營為單位前進。"},{"source_id":3149,"word":"beacon","meaning":"燈塔","example":"The harbor beacon guided the fishing boats home through the mist.","example_zh":"港口的燈塔引導漁船穿過薄霧返航。","original_meaning":"燈塔","original_example":"The lighthouse acted as a beacon in the dark.","original_example_zh":"燈塔在黑暗中充當了導航標誌。"},{"source_id":3150,"word":"benefactor","meaning":"恩人","example":"A generous benefactor donated instruments to the village music school.","example_zh":"一位慷慨的恩人捐贈樂器給村落音樂學校。","original_meaning":"恩人","original_example":"The benefactor donated a large sum to the hospital.","original_example_zh":"這位捐助者向醫院捐贈了一大筆款項。"},{"source_id":3151,"word":"benevolence","meaning":"仁慈","example":"Her benevolence was clear when she shared her lunch with a hungry neighbor.","example_zh":"她把午餐分給飢餓鄰居的舉動，展現了仁慈。","original_meaning":"仁慈","original_example":"Her benevolence made her popular in the community.","original_example_zh":"她的仁慈讓她在社區中廣受歡迎。"},{"source_id":3152,"word":"bequest","meaning":"遺贈","example":"The artist's bequest gave the town library a collection of rare books.","example_zh":"藝術家的遺贈讓鎮立圖書館得到一批珍貴藏書。","original_meaning":"遺贈","original_example":"The will included a generous bequest.","original_example_zh":"遺囑中包含了一筆慷慨的遺贈。"},{"source_id":3153,"word":"bibliography","meaning":"參考書目","example":"The student added a bibliography listing the books used for her project.","example_zh":"學生在專題後附上參考書目，列出用到的書籍。","original_meaning":"參考書目","original_example":"The thesis contains a detailed bibliography.","original_example_zh":"這篇論文包含一份詳盡的參考文獻目錄。"},{"source_id":3154,"word":"bilateral","meaning":"雙邊的","example":"The two schools signed a bilateral agreement to exchange student musicians.","example_zh":"兩校簽訂雙邊協議，交流學生音樂家。","original_meaning":"雙邊的","original_example":"The countries signed a bilateral agreement.","original_example_zh":"這些國家簽署了一項雙邊協定。"},{"source_id":3155,"word":"biodiversity","meaning":"生物多樣性","example":"The wetland's biodiversity includes birds, frogs, fish, and many insects.","example_zh":"這片濕地的生物多樣性包含鳥、青蛙、魚與許多昆蟲。","original_meaning":"生物多樣性","original_example":"Planting only one kind of tree does little to support biodiversity.","original_example_zh":"只種一種樹對維持生物多樣性的幫助不大。"},{"source_id":3156,"word":"bipartisan","meaning":"兩黨的","example":"The history class studied a bipartisan effort to protect the national park.","example_zh":"歷史課研究兩黨共同保護國家公園的努力。","original_meaning":"兩黨的","original_example":"The bill gained bipartisan support.","original_example_zh":"該法案獲得了兩黨的支持。"},{"source_id":3157,"word":"blemish","meaning":"瑕疵","example":"A small blemish on the apple did not spoil its fresh taste.","example_zh":"蘋果上的小瑕疵沒有影響新鮮口感。","original_meaning":"瑕疵","original_example":"There was a small blemish on the surface.","original_example_zh":"表面上有一處小小的瑕疵。"},{"source_id":3158,"word":"bloc","meaning":"集團","example":"The small clubs formed a voting bloc to support the shared practice room.","example_zh":"小社團組成投票集團，支持共用練習室。","original_meaning":"集團","original_example":"The nations formed a political bloc.","original_example_zh":"各國組成了一個政治集團。"},{"source_id":3159,"word":"blueprint","meaning":"藍圖","example":"The builders checked the blueprint before assembling the wooden shelter.","example_zh":"建造者組裝木棚前先查看藍圖。","original_meaning":"藍圖","original_example":"The engineer created a blueprint for the design.","original_example_zh":"工程師為該設計繪製了藍圖。"},{"source_id":3160,"word":"bondage","meaning":"束縛","example":"The museum tells how enslaved people struggled to escape bondage.","example_zh":"博物館講述被奴役的人如何努力擺脫束縛。","original_meaning":"束縛","original_example":"He struggled to escape emotional bondage.","original_example_zh":"他掙扎著想要擺脫情感的枷鎖。"},{"source_id":3161,"word":"bounty","meaning":"賞金","example":"The farmer offered a bounty for the safe return of his missing horse.","example_zh":"農夫提供賞金，希望有人把走失的馬安全帶回。","original_meaning":"賞金","original_example":"A bounty was offered for information.","original_example_zh":"當局懸賞徵求線索。"},{"source_id":3162,"word":"breakneck","meaning":"極速的","example":"The bicycle raced downhill at breakneck speed in the film.","example_zh":"電影裡的腳踏車以極快速度衝下山坡。","original_meaning":"極速的","original_example":"The car moved at a breakneck speed.","original_example_zh":"那輛車以驚人的速度疾馳。"},{"source_id":3163,"word":"breakthrough","meaning":"突破","example":"Finding a lighter material was a breakthrough for our model aircraft.","example_zh":"找到更輕的材料，是我們模型飛機製作的一大突破。","original_meaning":"突破","original_example":"The research led to a major breakthrough.","original_example_zh":"這項研究帶來了重大突破。"},{"source_id":3164,"word":"brethren","meaning":"弟兄","example":"The monk welcomed his brethren into the quiet hall.","example_zh":"修士歡迎弟兄們走進安靜的大廳。","original_meaning":"弟兄","original_example":"He welcomed his brethren warmly.","original_example_zh":"他熱情地歡迎他的兄弟們。"},{"source_id":3165,"word":"bribery","meaning":"賄賂","example":"The official refused the envelope because accepting it would be bribery.","example_zh":"官員拒收信封，因為接受它就是受賄。","original_meaning":"賄賂","original_example":"The politician was accused of bribery.","original_example_zh":"那位政治人物被指控收受賄賂。"},{"source_id":3166,"word":"broadband","meaning":"寬頻","example":"Broadband allowed the village school to join a live science lesson.","example_zh":"寬頻讓村落學校能參加即時科學課程。","original_meaning":"寬頻","original_example":"The area now has fast broadband internet.","original_example_zh":"該地區現在已擁有高速寬頻網路。"},{"source_id":3167,"word":"broker","meaning":"經紀人","example":"The broker helped the family compare several homes before buying one.","example_zh":"經紀人幫家人在購屋前比較幾間房子。","original_meaning":"經紀人","original_example":"The broker handled the deal professionally.","original_example_zh":"這位經紀人專業地處理了這筆交易。"},{"source_id":3168,"word":"brunt","meaning":"衝擊","example":"The old seawall took the brunt of the storm's waves.","example_zh":"老海堤承受了暴風雨海浪的大部分衝擊。","original_meaning":"衝擊","original_example":"The city took the brunt of the damage.","original_example_zh":"這座城市承受了最嚴重的破壞。"},{"source_id":3169,"word":"buffer","meaning":"緩衝","example":"A strip of trees formed a buffer between the playground and the busy road.","example_zh":"一排樹木在操場與繁忙道路之間形成緩衝。","original_meaning":"緩衝","original_example":"The buffer prevents data overflow.","original_example_zh":"緩衝區可防止資料溢出。"},{"source_id":3170,"word":"bulwark","meaning":"堡壘；屏障","example":"The thick stone wall served as a bulwark against the flood.","example_zh":"厚實石牆成為抵擋洪水的屏障。","original_meaning":"堡壘","original_example":"The castle served as a bulwark.","original_example_zh":"那座城堡充當了堡壘。"},{"source_id":3171,"word":"buoyant","meaning":"樂觀的","example":"The team remained buoyant despite the rain delaying their performance.","example_zh":"雖然雨勢延誤演出，小組仍保持樂觀。","original_meaning":"樂觀的","original_example":"She remained buoyant after the failure.","original_example_zh":"失敗後，她依然保持樂觀。"},{"source_id":3172,"word":"byproduct","meaning":"副產品","example":"Sawdust is a useful byproduct of cutting wood.","example_zh":"鋸木屑是切割木材產生的有用副產品。","original_meaning":"副產品","original_example":"Smoke is a byproduct of combustion.","original_example_zh":"煙是燃燒的副產品。"},{"source_id":3173,"word":"cadre","meaning":"幹部","example":"A small cadre of experienced volunteers trained the new members.","example_zh":"一小群有經驗的志工幹部訓練新成員。","original_meaning":"幹部","original_example":"The organization trained a new cadre.","original_example_zh":"該組織培訓了一名新幹部。"},{"source_id":3174,"word":"calamity","meaning":"災難","example":"The flood was a calamity for the village, but the neighbors helped one another.","example_zh":"洪水對村落是場災難，但鄰居彼此協助。","original_meaning":"災難","original_example":"The flood was a terrible calamity.","original_example_zh":"那場洪水是一場可怕的災難。"},{"source_id":3175,"word":"caliber","meaning":"口徑；水準","example":"The judges praised the high caliber of the students' musical performance.","example_zh":"評審讚賞學生音樂演出的高水準。","original_meaning":"口徑","original_example":"The weapon has a high caliber.","original_example_zh":"這把武器口徑很大。"},{"source_id":3176,"word":"camouflage","meaning":"偽裝","example":"The insect's camouflage made it look like a dry leaf.","example_zh":"昆蟲的偽裝讓牠看起來像乾枯葉片。","original_meaning":"偽裝","original_example":"The soldiers wore camouflage uniforms.","original_example_zh":"士兵們穿著迷彩服。"},{"source_id":3177,"word":"canopy","meaning":"樹冠","example":"Sunlight filtered through the dense canopy above the forest path.","example_zh":"陽光穿過森林步道上方濃密的樹冠。","original_meaning":"樹冠","original_example":"The canopy blocked the sunlight.","original_example_zh":"樹冠擋住了陽光。"},{"source_id":3178,"word":"captivity","meaning":"囚禁；圈養","example":"The injured bird recovered in captivity before being released into the wild.","example_zh":"受傷的鳥在圈養照護中康復後，被放回野外。","original_meaning":"囚禁","original_example":"The animal lived in captivity.","original_example_zh":"那隻動物生活在圈養環境中。"},{"source_id":3179,"word":"carcinogen","meaning":"致癌物","example":"The safety lesson explained why a carcinogen requires careful handling.","example_zh":"安全課程說明為何致癌物需要謹慎處理。","original_meaning":"致癌物","original_example":"Smoking exposes people to carcinogens.","original_example_zh":"吸菸會使人接觸致癌物質。"},{"source_id":3180,"word":"cardinal","meaning":"基本的","example":"Keeping the emergency exit clear is a cardinal rule in the workshop.","example_zh":"保持緊急出口暢通，是工坊的一項基本規則。","original_meaning":"基本的","original_example":"Honesty is a cardinal rule.","original_example_zh":"誠實是首要準則。"},{"source_id":3181,"word":"caretaker","meaning":"看護者；管理員","example":"The caretaker checked that every room was safe before the students arrived.","example_zh":"管理員在學生到達前，確認每個房間都安全。","original_meaning":"看護者","original_example":"The caretaker fed the animals.","original_example_zh":"管理員餵了動物。"},{"source_id":3182,"word":"catalyst","meaning":"催化劑","example":"The teacher showed how a catalyst can speed up a chemical reaction.","example_zh":"老師示範催化劑如何加快化學反應。","original_meaning":"催化劑","original_example":"The reaction needs a catalyst.","original_example_zh":"反應需要催化劑。"},{"source_id":3183,"word":"caustic","meaning":"腐蝕的","example":"The teacher handled the caustic liquid behind a protective screen.","example_zh":"老師在防護屏後操作腐蝕性液體。","original_meaning":"腐蝕的","original_example":"This chemical is highly caustic.","original_example_zh":"這種化學物質具有強腐蝕性。"},{"source_id":3184,"word":"cavalry","meaning":"騎兵","example":"The painting showed cavalry crossing the plain on horseback.","example_zh":"畫作呈現騎兵騎馬穿過平原。","original_meaning":"騎兵","original_example":"The cavalry charged forward.","original_example_zh":"騎兵隊向前衝鋒。"},{"source_id":3185,"word":"celestial","meaning":"天體的","example":"The planetarium helped us identify several celestial objects in the night sky.","example_zh":"天文館幫我們辨認夜空中的幾種天體。","original_meaning":"天體的","original_example":"Stars are celestial objects.","original_example_zh":"星星是天體。"},{"source_id":3186,"word":"censorship","meaning":"審查","example":"The exhibition showed how censorship had hidden parts of old newspapers.","example_zh":"展覽呈現審查制度如何遮蔽舊報紙的部分內容。","original_meaning":"審查","original_example":"The government enforced censorship.","original_example_zh":"政府實施了審查制度。"},{"source_id":3187,"word":"centennial","meaning":"百年","example":"The town celebrated its centennial with music in the main square.","example_zh":"城鎮以廣場音樂表演慶祝百年紀念。","original_meaning":"百年","original_example":"The city celebrated its centennial.","original_example_zh":"這座城市慶祝了其百年紀念。"},{"source_id":3188,"word":"ceramic","meaning":"陶瓷的","example":"The students made ceramic cups in the pottery workshop.","example_zh":"學生在陶藝工坊製作陶瓷杯。","original_meaning":"陶瓷的","original_example":"She collects ceramic art.","original_example_zh":"她收藏陶瓷藝術品。"},{"source_id":3189,"word":"chancellor","meaning":"總理；大學校長","example":"The chancellor addressed the students at the university ceremony.","example_zh":"大學校長在典禮上向學生致詞。","original_meaning":"總理","original_example":"The chancellor gave a speech.","original_example_zh":"校長發表了演說。"},{"source_id":3190,"word":"charisma","meaning":"魅力","example":"The young conductor's charisma inspired the whole orchestra.","example_zh":"年輕指揮的魅力鼓舞了整個管弦樂團。","original_meaning":"魅力","original_example":"His charisma impressed everyone.","original_example_zh":"他的魅力令所有人印象深刻。"},{"source_id":3191,"word":"charter","meaning":"憲章","example":"The club's charter explained its purpose and basic responsibilities.","example_zh":"社團章程說明它的宗旨與基本責任。","original_meaning":"憲章","original_example":"The company operates under a charter.","original_example_zh":"該公司根據章程運作。"},{"source_id":3192,"word":"chronicle","meaning":"編年史","example":"The museum's chronicle traced the town's growth from a fishing village.","example_zh":"博物館的編年史追溯城鎮從漁村開始的發展。","original_meaning":"編年史","original_example":"The book is a historical chronicle.","original_example_zh":"這本書是一部歷史編年史。"},{"source_id":3193,"word":"circulate","meaning":"流通；循環","example":"A small pump helps water circulate through the classroom aquarium.","example_zh":"小幫浦讓教室魚缸裡的水循環流動。","original_meaning":"流通","original_example":"Blood circulates through the body.","original_example_zh":"血液在體內循環。"},{"source_id":3194,"word":"citation","meaning":"引用","example":"The student included a citation to show where the information came from.","example_zh":"學生加入引用資料，說明資訊來源。","original_meaning":"引用","original_example":"The article includes proper citation.","original_example_zh":"該文章包含正確的引用。"},{"source_id":3195,"word":"clandestine","meaning":"秘密的","example":"The classmates held a clandestine meeting to plan a surprise concert.","example_zh":"同學悄悄開會，規劃一場驚喜音樂會。","original_meaning":"秘密的","original_example":"They had a clandestine meeting.","original_example_zh":"他們舉行了一次秘密會議。"},{"source_id":3196,"word":"clemency","meaning":"寬恕","example":"The story ended with the ruler granting clemency to the repentant prisoner.","example_zh":"故事以統治者寬赦悔過的囚犯作結。","original_meaning":"寬恕","original_example":"The prisoner was granted clemency.","original_example_zh":"囚犯獲得了特赦。"},{"source_id":3197,"word":"clientele","meaning":"客群","example":"The repair shop's clientele included musicians from across the town.","example_zh":"修理店的客群包含來自全鎮的音樂家。","original_meaning":"客群","original_example":"The business expanded its clientele.","original_example_zh":"該企業拓展了客戶群。"},{"source_id":3198,"word":"coalesce","meaning":"合併","example":"Several small streams coalesce into one river below the valley.","example_zh":"幾條小溪在山谷下方匯合成一條河流。","original_meaning":"合併","original_example":"The companies began to coalesce.","original_example_zh":"這些公司開始合併。"},{"source_id":3199,"word":"coerce","meaning":"強迫","example":"No one should coerce a classmate into joining an unwanted activity.","example_zh":"任何人都不該強迫同學參加不想參加的活動。","original_meaning":"強迫","original_example":"He tried to coerce them.","original_example_zh":"他試圖脅迫他們。"},{"source_id":3200,"word":"coexist","meaning":"共存","example":"Birds and people can coexist when the wetland paths are carefully planned.","example_zh":"只要妥善規劃濕地步道，鳥與人就能共存。","original_meaning":"共存","original_example":"Different cultures coexist peacefully.","original_example_zh":"不同文化和平共存。"},{"source_id":3201,"word":"cohesion","meaning":"凝聚力","example":"Practicing together strengthened the choir's cohesion.","example_zh":"一起練習增強了合唱團的凝聚力。","original_meaning":"凝聚力","original_example":"Team cohesion is essential.","original_example_zh":"團隊凝聚力至關重要。"},{"source_id":3202,"word":"coincidence","meaning":"巧合","example":"It was a coincidence that we both brought the same novel on the trip.","example_zh":"我們旅行時都帶了同一本小說，真是巧合。","original_meaning":"巧合","original_example":"It was just a coincidence.","original_example_zh":"這純屬巧合。"},{"source_id":3203,"word":"collateral","meaning":"抵押品","example":"The family offered its workshop as collateral for the business loan.","example_zh":"這個家庭以工作坊作為創業貸款的抵押品。","original_meaning":"抵押品","original_example":"The bank requires collateral.","original_example_zh":"銀行要求提供擔保品。"},{"source_id":3204,"word":"commemorate","meaning":"紀念","example":"The villagers planted a tree to commemorate the beloved teacher.","example_zh":"村民種下一棵樹，紀念深受愛戴的老師。","original_meaning":"紀念","original_example":"They commemorate the event yearly.","original_example_zh":"他們每年紀念這項活動。"},{"source_id":3205,"word":"commentary","meaning":"評論","example":"The coach provided commentary as we watched the recorded match.","example_zh":"我們看比賽錄影時，教練在旁講評。","original_meaning":"評論","original_example":"He wrote a political commentary.","original_example_zh":"他寫了一篇政治評論。"},{"source_id":3206,"word":"commissar","meaning":"政委","example":"The history lesson described a commissar supervising political education in the army.","example_zh":"歷史課介紹政委在軍隊中督導政治教育的工作。","original_meaning":"政委","original_example":"The commissar enforced rules.","original_example_zh":"政治委員執行規定。"},{"source_id":3207,"word":"communism","meaning":"共產主義","example":"The history class compared communism with other political and economic systems.","example_zh":"歷史課比較共產主義與其他政治經濟制度。","original_meaning":"共產主義","original_example":"Communism shaped many nations.","original_example_zh":"共產主義塑造了許多國家。"},{"source_id":3208,"word":"compact","meaning":"緊湊的；小巧的","example":"The compact toolbox fit neatly inside the student's backpack.","example_zh":"小巧的工具箱整齊放進學生的背包。","original_meaning":"緊湊的","original_example":"This phone is compact and light.","original_example_zh":"這支手機小巧輕便。"},{"source_id":3209,"word":"compassion","meaning":"同情","example":"The volunteers showed compassion by caring for the frightened rescue animals.","example_zh":"志工照顧受驚的獲救動物，展現同情與關懷。","original_meaning":"同情","original_example":"She showed great compassion.","original_example_zh":"她展現了極大的同情心。"},{"source_id":3210,"word":"compilation","meaning":"匯編","example":"The library displayed a compilation of stories written by local students.","example_zh":"圖書館展示一本當地學生故事的彙編。","original_meaning":"匯編","original_example":"The book is a compilation of essays.","original_example_zh":"這本書是一本散文集。"},{"source_id":3211,"word":"compliance","meaning":"遵從","example":"The instructor checked everyone's compliance with the workshop safety rules.","example_zh":"指導老師確認每個人都遵守工坊安全規定。","original_meaning":"遵從","original_example":"The company ensures compliance.","original_example_zh":"公司確保合規。"},{"source_id":3212,"word":"complication","meaning":"併發症；複雜情況","example":"The blocked pipe was an unexpected complication in our garden project.","example_zh":"水管堵塞是菜園計畫裡意想不到的複雜問題。","original_meaning":"併發症","original_example":"The surgery had complications.","original_example_zh":"手術出現了併發症。"},{"source_id":3213,"word":"composure","meaning":"沉著","example":"The violinist regained her composure after a brief mistake.","example_zh":"小提琴家短暫失誤後，恢復沉著。","original_meaning":"沉著","original_example":"He maintained his composure.","original_example_zh":"他保持了鎮定。"},{"source_id":3214,"word":"compulsion","meaning":"強迫；難以抗拒的衝動","example":"She felt a compulsion to check the door again, even after locking it.","example_zh":"即使已經鎖門，她仍有忍不住再檢查的衝動。","original_meaning":"強迫","original_example":"The behavior was driven by compulsion.","original_example_zh":"這種行為是出於強迫。"},{"source_id":3215,"word":"computation","meaning":"計算","example":"The students checked their computation before cutting the wooden beams.","example_zh":"學生切木梁前，先檢查計算結果。","original_meaning":"計算","original_example":"The result requires computation.","original_example_zh":"結果需要計算。"},{"source_id":3216,"word":"concession","meaning":"讓步","example":"Sharing the practice room was a concession both clubs accepted.","example_zh":"共用練習室是兩個社團都接受的讓步。","original_meaning":"讓步","original_example":"They made a concession.","original_example_zh":"他們做出了讓步。"},{"source_id":3217,"word":"concurrent","meaning":"同時的","example":"The festival had concurrent workshops in several rooms.","example_zh":"節慶在好幾個房間同時舉辦工作坊。","original_meaning":"同時的","original_example":"The events happened concurrently.","original_example_zh":"這些事件同時發生。"},{"source_id":3218,"word":"condemnation","meaning":"譴責","example":"The council expressed condemnation of the damage to the ancient temple.","example_zh":"委員會譴責破壞古廟的行為。","original_meaning":"譴責","original_example":"The act drew condemnation.","original_example_zh":"該行為招致譴責。"},{"source_id":3219,"word":"condensation","meaning":"凝結","example":"Condensation formed on the outside of the cold glass.","example_zh":"冷玻璃杯外側凝結了水珠。","original_meaning":"凝結","original_example":"Water vapor formed condensation.","original_example_zh":"水蒸氣形成凝結。"},{"source_id":3220,"word":"confederation","meaning":"邦聯","example":"The history model showed a confederation of small states cooperating.","example_zh":"歷史模型呈現小邦國組成邦聯、彼此合作。","original_meaning":"邦聯","original_example":"The states formed a confederation.","original_example_zh":"各州組成聯邦。"},{"source_id":3221,"word":"confiscate","meaning":"沒收","example":"The teacher had to confiscate the unsafe toy before the activity began.","example_zh":"活動開始前，老師必須沒收不安全的玩具。","original_meaning":"沒收","original_example":"Police confiscate illegal items.","original_example_zh":"警方沒收違禁物品。"},{"source_id":3222,"word":"congestion","meaning":"壅塞；擁擠","example":"The narrow road caused traffic congestion near the school gate.","example_zh":"狹窄道路讓校門附近交通壅塞。","original_meaning":"壅塞；擁擠","original_example":"Traffic congestion near the stadium delayed our bus after the concert.","original_example_zh":"演唱會後，體育場附近塞車使我們的公車延誤。"},{"source_id":3223,"word":"congregation","meaning":"會眾","example":"The congregation gathered quietly in the church before the service.","example_zh":"禮拜前，會眾安靜地聚集在教堂裡。","original_meaning":"會眾","original_example":"The congregation gathered for the ceremony.","original_example_zh":"會眾為儀式而聚集。"},{"source_id":3224,"word":"conjunction","meaning":"連接；共同進行","example":"The festival was organized in conjunction with the town library.","example_zh":"這場節慶與鎮立圖書館共同籌辦。","original_meaning":"連接","original_example":"Use a conjunction to connect the sentences.","original_example_zh":"使用連詞來連接句子。"},{"source_id":3225,"word":"conscription","meaning":"徵兵","example":"The exhibit explained how conscription required adults to enter military service.","example_zh":"展覽說明徵兵制度如何要求成年人服兵役。","original_meaning":"徵兵","original_example":"Conscription is mandatory in some countries.","original_example_zh":"某些國家實行強制徵兵制。"},{"source_id":3226,"word":"constituency","meaning":"選區","example":"The representative listened to families from across her constituency.","example_zh":"代表聆聽來自選區各地家庭的意見。","original_meaning":"選區","original_example":"The politician represents his constituency.","original_example_zh":"這位政治人物代表他的選區。"},{"source_id":3227,"word":"contagious","meaning":"傳染的；有感染力的","example":"Her contagious laughter soon made the whole group laugh.","example_zh":"她有感染力的笑聲，很快讓整組人都笑了起來。","original_meaning":"傳染的","original_example":"The disease is highly contagious.","original_example_zh":"這種疾病極具傳染性。"},{"source_id":3228,"word":"contaminate","meaning":"汙染","example":"Careless dumping can contaminate the water in the river.","example_zh":"隨意傾倒廢棄物可能汙染河水。","original_meaning":"汙染","original_example":"The water was contaminated by waste.","original_example_zh":"水被廢棄物污染了。"},{"source_id":3229,"word":"contemplation","meaning":"沉思","example":"The quiet garden offered a place for contemplation after a busy day.","example_zh":"安靜花園讓人在忙碌一天後有個沉思的地方。","original_meaning":"沉思","original_example":"He sat quietly in contemplation.","original_example_zh":"他靜靜地坐著沉思。"},{"source_id":3230,"word":"contingent","meaning":"視情況的","example":"The outdoor concert is contingent on the weather staying dry.","example_zh":"戶外音樂會是否舉行，要看天氣能否保持乾燥。","original_meaning":"視情況的","original_example":"The plan is contingent on approval.","original_example_zh":"該計畫取決於批准。"},{"source_id":3231,"word":"contraband","meaning":"走私品","example":"Customs officers found contraband hidden among the legal cargo.","example_zh":"海關人員在合法貨物之中發現藏匿的走私品。","original_meaning":"走私品","original_example":"The police seized illegal contraband.","original_example_zh":"警方查獲了非法走私品。"},{"source_id":3232,"word":"conundrum","meaning":"難題","example":"The missing piece left the puzzle club with a difficult conundrum.","example_zh":"遺失的那一片讓益智社遇上一道難題。","original_meaning":"難題","original_example":"This puzzle is a real conundrum.","original_example_zh":"這個謎題真是個難題。"},{"source_id":3233,"word":"convergence","meaning":"匯聚","example":"The convergence of three trails made this clearing a useful meeting point.","example_zh":"三條步道交會，讓這片空地成為方便的集合點。","original_meaning":"匯聚","original_example":"The convergence of ideas led to innovation.","original_example_zh":"思想的匯聚促成了創新。"},{"source_id":3234,"word":"coronation","meaning":"加冕","example":"The painting depicted the coronation of a young queen.","example_zh":"畫作描繪年輕女王的加冕典禮。","original_meaning":"加冕","original_example":"The king’s coronation was magnificent.","original_example_zh":"國王的加冕典禮盛大非凡。"},{"source_id":3235,"word":"corpse","meaning":"屍體","example":"The biologist examined the corpse of a small bird found after the storm.","example_zh":"生物學家檢查暴風雨後發現的一隻小鳥屍體。","original_meaning":"屍體","original_example":"The corpse was found in the forest.","original_example_zh":"屍體是在森林中被發現的。"},{"source_id":3236,"word":"corroborate","meaning":"證實","example":"The photographs helped corroborate the witness's account of the damaged bridge.","example_zh":"照片有助於證實目擊者對受損橋梁的描述。","original_meaning":"證實","original_example":"The evidence helped corroborate his story.","original_example_zh":"證據有助於佐證他的說法。"},{"source_id":3237,"word":"cosmopolitan","meaning":"國際化的","example":"The cosmopolitan market offered food and crafts from many cultures.","example_zh":"國際化的市場提供來自多種文化的食物與工藝品。","original_meaning":"國際化的","original_example":"She lives a cosmopolitan lifestyle.","original_example_zh":"她過著國際化的生活。"},{"source_id":3238,"word":"counterfeit","meaning":"偽造的","example":"The expert compared the counterfeit coin with a genuine one.","example_zh":"專家把偽造硬幣與真幣作比較。","original_meaning":"偽造的","original_example":"The goods turned out to be counterfeit.","original_example_zh":"那些貨物結果是假貨。"},{"source_id":3239,"word":"coup","meaning":"政變","example":"The history lesson examined how a coup suddenly changed the government.","example_zh":"歷史課探討政變如何突然改變政府。","original_meaning":"政變","original_example":"The coup changed the government.","original_example_zh":"政變改變了政府。"},{"source_id":3240,"word":"courtyard","meaning":"庭院","example":"The students rehearsed their music in the shaded courtyard.","example_zh":"學生在有樹蔭的庭院裡排練音樂。","original_meaning":"庭院","original_example":"They met in the courtyard.","original_example_zh":"他們在庭院裡見面。"},{"source_id":3241,"word":"creditor","meaning":"債權人","example":"The shop owner met with the creditor to discuss repaying the loan.","example_zh":"店主與債權人會面，討論償還貸款。","original_meaning":"債權人","original_example":"The creditor demanded repayment.","original_example_zh":"債權人要求還款。"},{"source_id":3242,"word":"crescent","meaning":"新月","example":"A thin crescent moon appeared above the town at dusk.","example_zh":"黃昏時，一彎細細的新月出現在城鎮上方。","original_meaning":"新月","original_example":"The moon appeared as a crescent.","original_example_zh":"月亮呈現新月狀。"},{"source_id":3243,"word":"criteria","meaning":"標準","example":"The judges used clear criteria to compare the students' models.","example_zh":"評審用明確標準比較學生模型。","original_meaning":"標準","original_example":"These criteria are used for evaluation.","original_example_zh":"這些標準用於評估。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-ballot-01-v1","level":"senior","word":"ballot","sort_order":1,"sense":"選票","alt_zh":"高中生依序把摺好的無字選票投入教室票箱。","example":"Each student placed a ballot in the box to choose the club president.","example_zh":"每位學生把選票投入票箱，選出社長。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ballot-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-bandwidth-01-v1","level":"senior","word":"bandwidth","sort_order":1,"sense":"頻寬","alt_zh":"高中生看教室螢幕上的影片載入圓圈，老師檢查網路設備。","example":"The school's limited bandwidth made the video lesson load slowly.","example_zh":"學校頻寬有限，讓影片課程載入緩慢。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/bandwidth-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-bane-01-v1","level":"senior","word":"bane","sort_order":1,"sense":"禍根","alt_zh":"高中生皺眉清理菜園裡反覆冒出的茂密雜草。","example":"The persistent weeds were the bane of our school garden.","example_zh":"頑強的雜草是我們校園菜園的一大禍根。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/bane-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-barricade-01-v1","level":"senior","word":"barricade","sort_order":1,"sense":"路障","alt_zh":"成年工人在裂開的步道入口擺放清楚可見的路障，遊客停在安全處。","example":"The workers placed a barricade across the damaged path.","example_zh":"工人在受損步道前設置路障。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/barricade-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-battalion-01-v1","level":"senior","word":"battalion","sort_order":1,"sense":"營","alt_zh":"歷史博物館的大型微縮模型中，多排成年士兵整齊行經石橋，無戰鬥。","example":"The museum model showed a battalion marching across an old bridge.","example_zh":"博物館模型呈現一個營的士兵走過老橋。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/battalion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-beacon-01-v1","level":"senior","word":"beacon","sort_order":1,"sense":"燈塔","alt_zh":"薄霧中的港口燈塔發出明亮光束，引導漁船安全返港。","example":"The harbor beacon guided the fishing boats home through the mist.","example_zh":"港口的燈塔引導漁船穿過薄霧返航。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/beacon-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-benefactor-01-v1","level":"senior","word":"benefactor","sort_order":1,"sense":"恩人","alt_zh":"成年捐贈者把新提琴交給音樂老師，學生開心在旁歡迎。","example":"A generous benefactor donated instruments to the village music school.","example_zh":"一位慷慨的恩人捐贈樂器給村落音樂學校。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/benefactor-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-benevolence-01-v1","level":"senior","word":"benevolence","sort_order":1,"sense":"仁慈","alt_zh":"成年女子友善地把一半便當交給需要幫助的鄰居。","example":"Her benevolence was clear when she shared her lunch with a hungry neighbor.","example_zh":"她把午餐分給飢餓鄰居的舉動，展現了仁慈。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/benevolence-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-bequest-01-v1","level":"senior","word":"bequest","sort_order":1,"sense":"遺贈","alt_zh":"圖書館員小心接收故藝術家的藏書與遺贈文件，桌上有藝術家相框。","example":"The artist's bequest gave the town library a collection of rare books.","example_zh":"藝術家的遺贈讓鎮立圖書館得到一批珍貴藏書。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/bequest-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-bibliography-01-v1","level":"senior","word":"bibliography","sort_order":1,"sense":"參考書目","alt_zh":"高中女生把研究用書整齊放在報告旁，整理最後一頁無可辨識文字的參考資料。","example":"The student added a bibliography listing the books used for her project.","example_zh":"學生在專題後附上參考書目，列出用到的書籍。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/bibliography-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-bilateral-01-v1","level":"senior","word":"bilateral","sort_order":1,"sense":"雙邊的","alt_zh":"兩位校長握手簽署文件，兩校高中樂團學生分站兩旁。","example":"The two schools signed a bilateral agreement to exchange student musicians.","example_zh":"兩校簽訂雙邊協議，交流學生音樂家。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/bilateral-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-biodiversity-01-v1","level":"senior","word":"biodiversity","sort_order":1,"sense":"生物多樣性","alt_zh":"高中生從步道觀察生氣蓬勃的濕地，同一場景可見鳥、青蛙、魚與蜻蜓。","example":"The wetland's biodiversity includes birds, frogs, fish, and many insects.","example_zh":"這片濕地的生物多樣性包含鳥、青蛙、魚與許多昆蟲。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/biodiversity-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-bipartisan-01-v1","level":"senior","word":"bipartisan","sort_order":1,"sense":"兩黨的","alt_zh":"兩組穿不同樸素顏色外套的成年議員一起查看森林保護模型，無黨徽。","example":"The history class studied a bipartisan effort to protect the national park.","example_zh":"歷史課研究兩黨共同保護國家公園的努力。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/bipartisan-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-blemish-01-v1","level":"senior","word":"blemish","sort_orde